INSERT INTO purpose VALUES('boot-core','','crate','Gives the bootstrap the operations on a range of bytes that allocate nothing: the `boot` layer, outside the integrity and the validity walls.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','Byte','struct','One byte that a fill writes or a search looks for.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','Found','enum','The answer of a search: the position of the first match, or an absence.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','Length','struct','A count of bytes: the length of a range.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','Place','struct','A range of bytes that a function writes, as an address and a length.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','Position','struct','The position of a byte in a range, counted from its first byte.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','Range','struct','A range of bytes that a function reads, as an address and a length.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','Short','struct','The refusal of a copy or a move into a place that is too short.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','Utf8','enum','The answer of the check of UTF-8: valid, or the position of the first fault.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','block','module','Copies, moves, fills and compares ranges of bytes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','block::compare','function','Orders two ranges by their first unequal byte, then by their length.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','block::copy','function','Writes a source into the start of a place with which it shares no byte.',NULL,'fits','sound',NULL);
