INSERT INTO purpose VALUES('boot-core','check::find_zero','function','Finds the first zero byte of a range, where a C string ends.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('boot-core','search','module','Finds a byte or a range of bytes in a range.',NULL,'fits','sound',NULL);
